            uv,
            "run",
            str(project.parent / "tools" / "make_logo_blob.py"),
            str(image),
            "--name",
            "grab_image_blob",
            "--size",
            str(GRAB_SIZE),
            "-o",
            str(header),
        ],
        check=True,
    )
